import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Report: TaggedValue::Tensor — the opaque-tensor kernel variant","description":"","frontmatter":{},"headers":[],"relativePath":"handl/project/reports/tagged-value-tensor.md","filePath":"vendored/handl/project/reports/tagged-value-tensor.md"}`),a={name:`handl/project/reports/tagged-value-tensor.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="report-taggedvalue-tensor-—-the-opaque-tensor-kernel-variant" tabindex="-1">Report: <code>TaggedValue::Tensor</code> — the opaque-tensor kernel variant <a class="header-anchor" href="#report-taggedvalue-tensor-—-the-opaque-tensor-kernel-variant" aria-label="Permalink to “Report: TaggedValue::Tensor — the opaque-tensor kernel variant”">​</a></h1><p>Date: this session. Commits: kernel <code>b57e922</code>, platform <code>224813ca</code>.</p><h2 id="what-landed" tabindex="-1">What landed <a class="header-anchor" href="#what-landed" aria-label="Permalink to “What landed”">​</a></h2><ul><li><strong><code>TaggedValue::Tensor(Rc&lt;TensorValue&gt;)</code></strong> in <code>handl-value</code> (kernel <code>5ed78ee..b57e922</code>). <code>TensorValue { shape: Vec&lt;usize&gt;, data: Rc&lt;Vec&lt;f64&gt;&gt; }</code> is a dense row-major <code>f64</code> tensor — <code>data.len() == product(shape)</code> is enforced by <code>TensorValue::new</code> (checked product, overflow rejected).</li><li><strong>Wire form is the host-tensor encoding</strong><code>{&quot;__tensor__&quot;: {&quot;shape&quot;: [...], &quot;data&quot;: [...], &quot;dtype&quot;: &quot;f64&quot;}}</code>, matching <code>host-tensor/src/ops.rs</code>&#39;s <code>encode_tensor</code>/<code>decode_tensor</code> exactly: <code>dtype</code> optional on decode, <code>&quot;f64&quot;</code> the only accepted value. Malformed payloads fall back to a plain object (the lenient <code>__bytes__</code>/<code>__sym__</code> convention), so a valid <code>__tensor__</code> object never silently changes rep either direction.</li><li><strong>A tensor is a value, not a handle</strong>: structural equality over shape + data (elementwise <code>f64</code> <code>==</code>, matching <code>Float</code> — <code>0.0 == -0.0</code>, <code>NaN</code> unequal to itself). <code>Hash</code> agrees: elements hash as <code>f64</code> bits with <code>-0.0</code> normalized to <code>+0.0</code>.</li><li><strong>Platform</strong>: the only non-exhaustive <code>TaggedValue</code> match in the workspace was <code>type_tag</code> (<code>plugin-engine-exec/src/native_ops.rs</code>); <code>typeof</code> now reports <code>&quot;tensor&quot;</code>, matching the lowercase scalar-tag convention (<code>&quot;bytes&quot;</code>, <code>&quot;resource&quot;</code>, <code>&quot;sym&quot;</code>).</li></ul><h2 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to “Findings”">​</a></h2><ul><li><strong><code>value_types.yaml</code> is inert spec</strong> — no code consumes it; the real runtime rep is the <code>TaggedValue</code> enum (<code>kernel/crates/handl-value</code>). The <code>host-tensor</code> doc comment anticipated this: &quot;promoting one in <code>value_types.yaml</code> later changes no wire shape&quot; — confirmed, the wire form is unchanged.</li><li><strong>The VM stays generic</strong>: engines pass <code>Tensor</code> through host fns; no <code>is_tensor</code> dispatch was added anywhere in an engine. <code>field_access</code> on a tensor is a type error (same as <code>Sym</code>/<code>Resource</code>); <code>arrow_free</code> treats it as substitutable literal data (it round-trips JSON losslessly); <code>check_portable</code> accepts it (self-contained data, unlike <code>__resource__</code>).</li><li><strong><code>ValueAbi</code></strong> (<code>plugin-compile</code>) does not know <code>__tensor__</code>: it flows through as a generic <code>Object</code> and round-trips — the carrier contract. The reserved-key list in <code>ValueAbi::check</code> (<code>__pair__</code>, <code>__either__</code>, <code>__arrow__</code>, <code>__bytes__</code>, <code>__resource__</code>) was left unchanged — <code>__sym__</code> is already absent from it, and adding <code>__tensor__</code> would reject legitimate tensor payloads crossing the ABI as objects.</li></ul><h2 id="deferred" tabindex="-1">Deferred <a class="header-anchor" href="#deferred" aria-label="Permalink to “Deferred”">​</a></h2><ul><li><code>host-tensor</code> could adopt <code>TaggedValue::as_tensor</code>/<code>tensor()</code> instead of its local <code>Tensor</code> codec — not done (out of scope; the wire form is identical either way).</li><li>A <code>Tensor</code> entry in <code>lang</code>&#39;s <code>value_types.yaml</code> would keep the spec in sync; skipped because the file is inert.</li><li><code>Eq</code> caveat inherited: <code>f64</code> <code>==</code> is non-reflexive for <code>NaN</code>, so <code>TaggedValue</code>&#39;s <code>impl Eq</code> remains technically loose (pre-existing <code>Float</code> behavior; <code>Tensor</code> follows the same convention).</li></ul>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};